/** `belay serve`: builds `web/` when its sources changed, then runs `next start` on loopback. */
import { spawn, spawnSync } from 'node:child_process';
import { existsSync, readdirSync, statSync } from 'node:fs';
import { createServer } from 'node:net';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { dataDir } from './config.ts';

const ROOT = fileURLToPath(new URL('..', import.meta.url));

// Generated by Next or by `tsc`, so they'd make every build look stale.
const SKIP = new Set(['node_modules', '.next', 'next-env.d.ts']);
const skipped = (name: string) => SKIP.has(name) || name.endsWith('.tsbuildinfo') || name.endsWith('.stackdump');

/** Newest file mtime under `dir`, in ms; 0 if there are no files. */
export function newestMtime(dir: string): number {
  let newest = 0;
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (skipped(e.name)) continue;
    const path = join(dir, e.name);
    newest = Math.max(newest, e.isDirectory() ? newestMtime(path) : statSync(path).mtimeMs);
  }
  return newest;
}

/** True when `web/.next/BUILD_ID` is missing or older than any source under `web/` or `src/`. */
export function buildStale(root: string): boolean {
  const buildId = join(root, 'web', '.next', 'BUILD_ID');
  if (!existsSync(buildId)) return true;
  const built = statSync(buildId).mtimeMs;
  return newestMtime(join(root, 'web')) > built || newestMtime(join(root, 'src')) > built;
}

function portFree(port: number): Promise<boolean> {
  return new Promise((resolve) => {
    const probe = createServer();
    probe.once('error', () => resolve(false));
    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
  });
}

async function waitUntilUp(url: string, timeoutMs = 30_000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      await fetch(url, { method: 'HEAD' });
      return true;
    } catch {
      await new Promise((r) => setTimeout(r, 200));
    }
  }
  return false;
}

function openBrowser(url: string): void {
  const [cmd, args] =
    process.platform === 'win32'
      ? ['cmd', ['/c', 'start', '', url]]
      : process.platform === 'darwin'
        ? ['open', [url]]
        : ['xdg-open', [url]];
  const child = spawn(cmd, args, { detached: true, stdio: 'ignore' });
  child.on('error', () => {});
  child.unref();
}

export async function serve({ port, open }: { port: number; open: boolean }): Promise<void> {
  const web = join(ROOT, 'web');
  // Run Next's JS entry with this Node rather than `.bin/next`, which is a .cmd shim on Windows.
  const next = join(web, 'node_modules', 'next', 'dist', 'bin', 'next');
  if (!existsSync(next)) throw new Error(`web/ dependencies missing — run 'npm install' in ${web}`);
  if (!(await portFree(port))) throw new Error(`port ${port} is in use — already running? (try --port)`);

  // dataDir() resolves BELAY_DATA to an absolute path, so a relative one survives the cwd change.
  const env = { ...process.env, BELAY_DATA: dataDir(), PORT: String(port) };
  if (buildStale(ROOT)) {
    console.log('belay: building the dashboard…');
    const build = spawnSync(process.execPath, [next, 'build'], { cwd: web, env, stdio: 'inherit' });
    if (build.status !== 0) throw new Error('next build failed');
  }

  const child = spawn(process.execPath, [next, 'start', '-H', '127.0.0.1', '-p', String(port)], { cwd: web, env, stdio: 'inherit' });
  child.on('exit', (code) => process.exit(code ?? 0));
  const url = `http://127.0.0.1:${port}/`;
  if ((await waitUntilUp(url)) && open) openBrowser(url);
}
